		function toggle_time_slot() {
						
			// Add toggle on time slots			
			$('body .bew-checkout-delivery button').on('click',function () {			
				//$(this).parents('.option-select').find('.time-slots-container:not(".next-day-collapse")').slideToggle();
				
				if($(this).parents('.option-select').find('.time-slots-container').hasClass('show')){	
					$(this).parents('.option-select').find('.time-slots-container').removeClass('show');					
				} else {
					
					$('.option-select').find('.list-item').removeClass('active');
					$('.option-select').find('.list-item').siblings().removeClass('d-none');
					$('.option-select').find('button').removeClass('active');
					$('.option-select').find('.time-slots-container').removeClass('show');
					$(this).parents('.option-select').find('.time-slots-container:not(".next-day-collapse")').addClass('show');
				}
			});	
						

		}
		function convertTime12to24( time12h ) {
			var time = time12h.split( ' ' );
			if ( time[ 1 ] ) {
				var _timesplit = time[ 0 ].split( ':' ),
					hours = _timesplit[ 0 ],
					minutes = _timesplit[ 1 ];
				return (
					( hours = 1 === hours.length ? 0 + hours : hours ),
					'12' === hours && ( hours = '00' ),
					'PM' === time[ 1 ] &&
						( hours = parseInt( hours, 10 ) + 12 ),
					hours + ':' + minutes
				);
			}
			return time12h;
		}
